#include "FortressJobPipeline.hpp"
namespace elysium::jobs {bool FortressJobPipeline::add(Job j,std::string&w){if(!j.id||!j.type){w="invalid job";return false;}if(!jobs_.emplace(j.id,std::move(j)).second){w="duplicate job";return false;}return true;}std::optional<StableId>FortressJobPipeline::assign(StableId id,const std::vector<WorkerCandidate>&c,std::string&w){auto i=jobs_.find(id);if(i==jobs_.end()){w="unknown job";return std::nullopt;}std::vector<WorkerCandidate>v;for(auto x:c)if(x.eligible)v.push_back(x);if(v.empty()){w="no eligible worker";return std::nullopt;}std::sort(v.begin(),v.end(),[](auto&a,auto&b){return a.score==b.score?a.worker<b.worker:a.score>b.score;});i->second.worker=v.front().worker;i->second.state=JobState::Assigned;return i->second.worker;}bool FortressJobPipeline::reserve(StableId id,StableId resource,std::string&w){auto i=jobs_.find(id);if(i==jobs_.end()){w="unknown job";return false;}auto r=reservations_.find(resource);if(r!=reservations_.end()&&r->second!=id){w="reservation conflict";return false;}reservations_[resource]=id;i->second.reservation=resource;i->second.state=JobState::Reserved;return true;}bool FortressJobPipeline::begin(StableId id,std::uint64_t rev,std::string&w){auto i=jobs_.find(id);if(i==jobs_.end()){w="unknown job";return false;}if(i->second.worldRevision!=rev){w="stale world revision";i->second.state=JobState::Failed;return false;}if(!i->second.worker){w="worker missing";return false;}i->second.state=JobState::Executing;return true;}bool FortressJobPipeline::markCommitPending(StableId id){auto i=jobs_.find(id);if(i==jobs_.end()||i->second.state!=JobState::Executing)return false;i->second.state=JobState::CommitPending;return true;}bool FortressJobPipeline::settle(StableId id,bool ok){auto i=jobs_.find(id);if(i==jobs_.end()||i->second.state!=JobState::CommitPending)return false;i->second.state=ok?JobState::Completed:JobState::Failed;if(i->second.reservation)reservations_.erase(i->second.reservation);return true;}std::optional<Job>FortressJobPipeline::get(StableId id)const{auto i=jobs_.find(id);if(i==jobs_.end())return std::nullopt;return i->second;}}
